lprof2 = 0;
ret1 = vec3 (.1,.15,.2);
mask2 = 0;
for (n=anz; n >= 1; n--) {
//  if (q28%3 == 0) {mov = -mov / 2.0 ;}
dist = n-.5+q31; lav_gnd = 0;
for (m=1; m <= quality; m++) {
rsl = project (dist)+vec3 (mov, 0.0 ) + n / 2.0;
lprof =  .5-lum(GetBlur1(fract(rsl.xy))); //mittelwert null !#
lav_gnd -= lprof/quality*depth/rsl.z;
}
rsl = project (dist)+vec3 (mov, 0.0 ) +n / 2.0;
rsl2 = project (dist)+vec3 (mov*.9, 0.0 );
shadow = clamp01(4.0 * GetBlur1(fract(rsl2.xy)));// * !(n == 1);
neu = GetPixel(fract(rsl.xy));
mask = clamp01(8.0 * neu);
neu *= 1-.7*lum(texture(sampler_noise_lq,rsl.xy * 4.0));
neu *= (1.0 - shadow*rand_preset.z / 2.0) ;
//  neu *= clamp01(3.0 - abs(rsl.z)) ; // Abdunkelung hinten
//  neu = mix( 0.0 , neu, clamp01(15.0 - rsl.z / 4.0)); // Nebel
ret1 = mix(ret1,neu,mask) ;
lprof2 = mix(lprof2,lprof,mask);
mask2 = mix(mask2,mask,mask);
}
rsl = project (dist)+vec3 (mov+lprof2 / 4.0, 0.0 );
vec2 noise = texture(sampler_noise_hq, rsl+uTime*.1).xy;
vec3 sun = ret1/length(sin(rsl.xy * 16.0+noise));
ret1 +=  sun* (1+0*q22)*vec3(.3,.6, 1.0 );
ret = vec3( 1.0 ) - exp(.1-ret1) ;
}
